      var theirs = x && (x.code === 'taken' || x.code === 'shape');
      var why = x && x.code === 'taken' ? '@' + v + ' is taken. Try another.'
        : x && x.code === 'shape' ? 'That username can’t be used. Try another.'
        : frWhy('username', x, 'Couldn’t save that. Try again.');
