    var label = h('span', { class: 'fr-label' });
    var say = function () { var a = frAge(f.birth); label.textContent = a == null ? 'Birthday' : 'Birthday (' + plural(a, 'year') + ' old)'; };
    var nx = { label: 'Next', ready: frAge(f.birth) != null, onTap: frSaveBirth };
